import re,sys
def items(p):
    d={}; cur=None; buf=[]
    for l in open(p,encoding='utf-8'):
        m=re.match(r'^(?:- \*\*)?(\d+)[.,] ',l)
        if m:
            if cur: d.setdefault(cur,[]).append(''.join(buf))
            cur=int(m.group(1)); buf=[l]
        elif l.startswith('#'):
            if cur: d.setdefault(cur,[]).append(''.join(buf))
            cur=None; buf=[]
        elif cur: buf.append(l)
    if cur: d.setdefault(cur,[]).append(''.join(buf))
    return d
b=items(sys.argv[1]); o=items(sys.argv[2])
ch=[n for n in sorted(set(b)|set(o)) if n<326 and b.get(n)!=o.get(n)]
print("changed old items:",ch)
EOF
